  "deed.quran-reflection.label": "معنی پر غور کیا (تدبر)",
  "deed.renew-tomorrow.exp": "اللہ کے نزدیک سب سے پسندیدہ عمل وہ ہے جو ہمیشہ کیا جائے۔",
  "deed.renew-tomorrow.label": "کل کے لیے نیت تازہ کی",
